import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class CodeProblem {

    class Pair {
        String first;
        int second;

        public Pair(String first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    public static void main(String[] args) throws IOException {
        CodeProblem app = new CodeProblem();
        app.solve();
    }

    public void solve() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        int t = Integer.parseInt(reader.readLine());
        for (int i = 0; i < t; i++) {
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine(), " ");
            int n = Integer.parseInt(tokenizer.nextToken());
            int h = Integer.parseInt(tokenizer.nextToken());
            List<Pair> pairs = new ArrayList<>();
            for (int j = 0; j < h; j++) {
                tokenizer = new StringTokenizer(reader.readLine(), " ");
                String first = tokenizer.nextToken();
                int second = Integer.parseInt(tokenizer.nextToken());
                int third = Integer.parseInt(tokenizer.nextToken());
                pairs.add(new Pair(first, second));
            }
            long[] res = new long[3];
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < n; k++) {
                    res[j] += solve(j, pairs, k) * (k + 1);
                }
            }
            writer.println(res[0] + " " + res[1] + " " + res[2]);
        }

        writer.close();
    }

    private long solve(int index, List<Pair> pairs, int k) {
        if (index == 2) {
            return 0;
        }
        long ans = 0;
        for (int i = 0; i < pairs.size(); i++) {
            Pair pair = pairs.get(i);
            if (pair.first.equals("xy")) {
                if (index == 0 && pair.second == k) {
                    return 1;
                }
                if (index == 1 && pair.second == k) {
                    return Math.pow(k + 1, 2);
                }
            } else if (pair.first.equals("xz")) {
                if (index == 0 && pair.second == k) {
                    return Math.pow(k + 1, 2);
                }
                if (index == 1 && pair.second == k) {
                    return 1;
                }
            } else {
                if (index!= 1) {
                    if (pair.second == k) {
                        return 1;
                    }
                }
            }
            ans += solve(index + 1, pairs, k);
        }
        return ans;
    }

}
